import { getDb, issues, projectMembers, projects } from "@/server/db";
import { CLOSED_ISSUE_STATUSES } from "@/types/issue";
import { toIsoTimestamp } from "@/types/common";
import { livePredicate, orgPredicate } from "./base-repository";
import { compact, keysetPredicate, probeLimit, toPage } from "./_paging";
import { toProject } from "./_mappers";
import type {
  CreateProjectInput,
  ListProjectsInput,
  UpdateProjectInput,
} from "@/schemas/project";
import type { ArchiveScope, OrgId, Page, ProjectId, UserId } from "@/types/common";
import type { Project, ProjectStats } from "@/types/project";

/**
 * Projects a non-admin actor may see: anything that is not `private`, plus
 * private projects they lead or have been added to. Admins, owners and
 * platform staff skip this filter and see every project in the org.
 */
export function visibleProjectIds(orgId: OrgId, userId: UserId) {
  const memberIds = getDb()
    .select({ id: projectMembers.projectId })
    .from(projectMembers)
    .where(
      and(
        orgPredicate(projectMembers.orgId, orgId),
        eq(projectMembers.userId, userId),
      ),
    );

  return getDb()
    .select({ id: projects.id })
    .from(projects)
    .where(
      and(
        orgPredicate(projects.orgId, orgId),
        or(
          ne(projects.visibility, "private"),
          eq(projects.leadId, userId),
          inArray(projects.id, memberIds),
        ),
      ),
    );
}

