import { isProjectMember } from "@/server/repositories/project-member-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import {
  actorEnvelope,
  NotFoundError,
  orgResource,
  projectResource,
  requireFound,
} from "./_support";
import type {
  ArchiveProjectInput,
  CreateProjectInput,
  ListProjectsInput,
  UpdateProjectInput,
} from "@/schemas/project";
import type { OrgId, Page, ProjectId, UserId } from "@/types/common";
import { hasRoleAtLeast, type Actor } from "@/types/member";
import type { Project, ProjectWithStats } from "@/types/project";

/**
 * Whether `actor` may see `project`. `org` and `public` projects are visible
 * to the whole tenant. A `private` project is visible only to an admin or
 * owner, platform staff, the project's lead, or an explicit project member.
 * Anyone else must be treated as though the project did not exist.
 */
export async function canViewProject(
  actor: Actor,
  project: Project,
): Promise<boolean> {
  if (project.visibility !== "private") return true;
  if (actor.orgId !== project.orgId) return false;
  if (actor.isPlatformStaff === true) return true;
  if (hasRoleAtLeast(actor.role, "admin")) return true;
  if (project.leadId === actor.userId) return true;
  return isProjectMember(project.orgId, project.id, actor.userId);
}

/**
 * `undefined` when `actor` can see every private project in the org (admin,
 * owner, or platform staff). Otherwise the user id listings must be narrowed to.
 */
export function privateListingUser(actor: Actor): UserId | undefined {
  if (actor.isPlatformStaff === true || hasRoleAtLeast(actor.role, "admin")) {
    return undefined;
  }
  return actor.userId;
}

async function assertProjectVisible(
  actor: Actor,
  project: Project,
  id: string,
): Promise<void> {
  if (!(await canViewProject(actor, project))) {
    throw new NotFoundError("Project", id);
  }
}

