import type { Comment, CommentThreadNode } from "@/types/comment";
import type { IssueId, OrgId, UserId } from "@/types/common";
import type { Actor } from "@/types/member";

/**
 * A comment on an issue inside a hidden private project is reported as missing.
 * `entity`/`id` match the caller's lookup so the two cases stay indistinguishable.
 */
async function assertIssueVisible(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
  entity: string,
  id: string,
): Promise<void> {
  const issue = await issueRepo.findIssueById(orgId, issueId);
  if (issue === null) return;
  const project = await projectRepo.findProjectById(orgId, issue.projectId);
  if (project !== null && !(await canViewProject(actor, project))) {
    throw new NotFoundError(entity, id);
  }
}

