/**
 * Temporary coverage for private-project visibility. Deleted after the check.
 */
import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
vi.mock("@/lib/rate-limit", async () => (await import("../server/_support/doubles/misc")).rateLimitModule);

import { PermissionDeniedError } from "@/lib/permissions";
import { NotFoundError } from "@/server/services/_support";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as projectMemberRepo from "@/server/repositories/project-member-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as commentService from "@/server/services/comment-service";
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { Comment } from "@/types/comment";
import type { Issue } from "@/types/issue";
import type { Actor } from "@/types/member";
import type { Project } from "@/types/project";

let cleanup: () => void;
let tenant: Tenant;
let secret: Project;
let open: Project;
let secretIssue: Issue;
let openIssue: Issue;
let secretComment: Comment;

function staff(actor: Actor): Actor {
  return { ...actor, isPlatformStaff: true };
}

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("privacy", "growth");

  secret = await projectService.createProject(tenant.actors.admin, {
    orgId: tenant.org.id,
    name: "Secret",
    slug: "secret",
    key: "SEC",
    description: null,
    visibility: "private",
    leadId: tenant.userIds.viewer,
    color: "#111111",
    targetDate: null,
  });

  open = await projectService.createProject(tenant.actors.member, {
    orgId: tenant.org.id,
    name: "Open",
    slug: "open",
    key: "OPN",
    description: null,
    visibility: "public",
    leadId: null,
    color: "#222222",
    targetDate: null,
  });

  secretIssue = await issueService.createIssue(
    tenant.actors.admin,
    issueInput(tenant.org.id, secret.id, { title: "Secret issue" }),
  );
  openIssue = await issueService.createIssue(
    tenant.actors.member,
    issueInput(tenant.org.id, open.id, { title: "Open issue" }),
  );
  secretComment = await commentService.createComment(tenant.actors.admin, {
    orgId: tenant.org.id,
    issueId: secretIssue.id,
    body: "secret note",
    parentId: null,
    mentionedUserIds: [],
  });
});

afterAll(() => {
  cleanup();
});

describe("canViewProject", () => {
  it("hides a private project from a plain member and shows it to the allowed set", async () => {
    expect(await projectService.canViewProject(tenant.actors.member, secret)).toBe(false);
    expect(await projectService.canViewProject(tenant.actors.admin, secret)).toBe(true);
    expect(await projectService.canViewProject(tenant.actors.owner, secret)).toBe(true);
    expect(await projectService.canViewProject(staff(tenant.actors.member), secret)).toBe(true);
    expect(await projectService.canViewProject(tenant.actors.viewer, secret)).toBe(true);

    expect(await projectService.canViewProject(tenant.actors.member, open)).toBe(true);
    expect(await projectService.canViewProject(tenant.actors.viewer, tenant.project)).toBe(true);
  });

  it("follows membership and lead changes immediately", async () => {
    await projectMemberRepo.addProjectMember(tenant.org.id, secret.id, tenant.userIds.member);
    expect(await projectService.canViewProject(tenant.actors.member, secret)).toBe(true);

    await projectMemberRepo.removeProjectMember(tenant.org.id, secret.id, tenant.userIds.member);
    expect(await projectService.canViewProject(tenant.actors.member, secret)).toBe(false);

    const previousLead = secret.leadId;
    await projectRepo.updateProject({
      orgId: tenant.org.id,
      projectId: secret.id,
      leadId: tenant.userIds.member,
    });
    const led = (await projectRepo.findProjectById(tenant.org.id, secret.id))!;
    expect(await projectService.canViewProject(tenant.actors.member, led)).toBe(true);
    expect(await projectService.canViewProject(tenant.actors.viewer, led)).toBe(false);

    await projectRepo.updateProject({
      orgId: tenant.org.id,
      projectId: secret.id,
      leadId: previousLead,
    });
    secret = (await projectRepo.findProjectById(tenant.org.id, secret.id))!;
  });
});

describe("lookups and writes", () => {
  it("throws NotFoundError and does not mutate", async () => {
    const member = tenant.actors.member;
    await expect(
      projectService.getProject(member, tenant.org.id, secret.slug),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      issueService.getIssue(member, tenant.org.id, secretIssue.id),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      issueService.getBoard(member, tenant.org.id, secret.id),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      commentService.getThread(member, tenant.org.id, secretIssue.id),
    ).rejects.toBeInstanceOf(NotFoundError);

    await expect(
      projectService.updateProject(member, {
        orgId: tenant.org.id,
        projectId: secret.id,
        name: "Renamed",
      }),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      projectService.archiveProject(member, {
        orgId: tenant.org.id,
        projectId: secret.id,
        archiveIssues: true,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);

    await projectService.archiveProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      projectId: secret.id,
      archiveIssues: false,
    });
    await expect(
      projectService.restoreProject(member, tenant.org.id, secret.id),
    ).rejects.toBeInstanceOf(NotFoundError);
    await projectService.restoreProject(tenant.actors.admin, tenant.org.id, secret.id);

    const stored = await projectRepo.findProjectById(tenant.org.id, secret.id);
    expect(stored?.name).toBe("Secret");
    expect(stored?.archivedAt).toBeNull();

    await expect(
      issueService.createIssue(member, issueInput(tenant.org.id, secret.id, { title: "Nope" })),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      issueService.updateIssue(member, {
        orgId: tenant.org.id,
        issueId: secretIssue.id,
        title: "Hijacked",
      }),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      issueService.changeIssueStatus(member, {
        orgId: tenant.org.id,
        issueId: secretIssue.id,
        status: "done",
      }),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      issueService.moveIssue(member, {
        orgId: tenant.org.id,
        issueId: secretIssue.id,
        toStatus: "todo",
        toIndex: 0,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      issueService.assignIssue(member, {
        orgId: tenant.org.id,
        issueId: secretIssue.id,
        assigneeId: tenant.userIds.member,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      issueService.archiveIssue(member, tenant.org.id, secretIssue.id),
    ).rejects.toBeInstanceOf(NotFoundError);

    const issue = await issueRepo.findIssueById(tenant.org.id, secretIssue.id);
    expect(issue?.title).toBe("Secret issue");
    expect(issue?.status).toBe("backlog");
    expect(issue?.assigneeId).toBeNull();
    expect(issue?.archivedAt).toBeNull();

    await expect(
      commentService.createComment(member, {
        orgId: tenant.org.id,
        issueId: secretIssue.id,
        body: "leak",
        parentId: null,
        mentionedUserIds: [],
      }),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      commentService.updateComment(member, {
        orgId: tenant.org.id,
        commentId: secretComment.id,
        body: "edited",
      }),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      commentService.deleteComment(member, {
        orgId: tenant.org.id,
        commentId: secretComment.id,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);

    const comment = await commentRepo.findCommentById(tenant.org.id, secretComment.id);
    expect(comment?.body).toBe("secret note");
    expect(comment?.archivedAt).toBeNull();
  });

  it("still lets a project member read and a viewer who is only the lead read", async () => {
    await projectMemberRepo.addProjectMember(tenant.org.id, secret.id, tenant.userIds.member);
    const found = await issueService.getIssue(
      tenant.actors.member,
      tenant.org.id,
      secretIssue.id,
    );
    expect(found.issue.id).toBe(secretIssue.id);
    await projectMemberRepo.removeProjectMember(tenant.org.id, secret.id, tenant.userIds.member);

    const thread = await commentService.getThread(
      tenant.actors.viewer,
      tenant.org.id,
      secretIssue.id,
    );
    expect(thread.length).toBeGreaterThan(0);

    await expect(
      issueService.createIssue(
        tenant.actors.viewer,
        issueInput(tenant.org.id, secret.id, { title: "Viewer cannot write" }),
      ),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
  });
});

describe("listings", () => {
  it("omits the private project and its issues from totals for a plain member", async () => {
    const projects = await projectService.listProjects(tenant.actors.member, {
      orgId: tenant.org.id,
      limit: 25,
      cursor: null,
    });
    expect(projects.items.map((row) => row.project.id)).not.toContain(secret.id);
    expect(projects.items.map((row) => row.project.id)).toContain(open.id);
    expect(projects.items.map((row) => row.project.id)).toContain(tenant.project.id);
    expect(projects.total).toBe(projects.items.length);

    const issues = await issueService.listIssues(tenant.actors.member, {
      orgId: tenant.org.id,
      limit: 25,
      cursor: null,
    });
    expect(issues.items.map((row) => row.id)).not.toContain(secretIssue.id);
    expect(issues.items.map((row) => row.id)).toContain(openIssue.id);
    expect(issues.total).toBe(issues.items.length);

    const asAdmin = await issueService.listIssues(tenant.actors.admin, {
      orgId: tenant.org.id,
      limit: 25,
      cursor: null,
    });
    expect(asAdmin.items.map((row) => row.id)).toContain(secretIssue.id);

    const asLead = await projectService.listProjects(tenant.actors.viewer, {
      orgId: tenant.org.id,
      limit: 25,
      cursor: null,
    });
    expect(asLead.items.map((row) => row.project.id)).toContain(secret.id);
    expect(asLead.total).toBe(asLead.items.length);
  });
});

